#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    int n, b;
    std::cin >> n >> b;
    std::vector<int> array(n);
    int evenCount = 0, oddCount = 0;
    for (int i = 0; i < n; i++) {
        std::cin >> array[i];
        if (array[i] % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
    }
    if (evenCount != oddCount) {
        std::cout << 0 << std::endl;
    } else {
        std::vector<int> differences;
        int evenPairs = 0, oddPairs = 0;
        for (int i = 0; i < n - 1; i++) {
            if (array[i] % 2 == 0) {
                evenPairs++;
            } else {
                oddPairs++;
            }
            if (evenPairs == oddPairs) {
                differences.push_back(std::abs(array[i + 1] - array[i]));
            }
        }
        std::sort(differences.begin(), differences.end());
        int sum = 0, count = 0;
        for (int diff : differences) {
            if (sum + diff <= b) {
                sum += diff;
                count++;
            } else {
                break;
            }
        }
        std::cout << count << std::endl;
    }
    return 0;
}
